/* ── Password Screen ── */
function PasswordScreen({ onUnlock }) {
  const [pin, setPin] = useState('')
  const [shake, setShake] = useState(false)
  const [leaving, setLeaving] = useState(false)
  const [visible, setVisible] = useState(false)
  const [success, setSuccess] = useState(false)
  const CORRECT = '0601'

  useEffect(() => { setTimeout(() => setVisible(true), 80) }, [])

  const handleKey = (digit) => {
    if (pin.length >= 4 || shake || success) return
    const next = pin + digit
    setPin(next)
    if (next.length === 4) {
      if (next === CORRECT) {
        setSuccess(true)
        setTimeout(() => { setLeaving(true); setTimeout(onUnlock, 550) }, 500)
      } else {
        setTimeout(() => {
          setShake(true)
          setTimeout(() => { setShake(false); setPin('') }, 620)
        }, 150)
      }
    }
  }
  const handleDel = () => { if (!shake && !success) setPin(p => p.slice(0,-1)) }
  const keys = ['1','2','3','4','5','6','7','8','9','','0','⌫']

  return (
    <div style={{
      position:'fixed', inset:0, zIndex:200,
      background:'linear-gradient(160deg, #FFF0F7 0%, #FDF4FF 50%, #FFF7FD 100%)',
      display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center',
      opacity: leaving ? 0 : 1, transition:'opacity 0.55s ease',
      overflow:'hidden',
    }}>
      <FloatingParticles count={6} />
      <div style={{ position:'absolute', top:-50, right:-50, width:200, height:200, borderRadius:'50%', background:'rgba(244,114,182,0.09)', animation:'driftBlob 9s ease-in-out infinite', pointerEvents:'none' }} />

      <div style={{
        position:'relative', zIndex:1, textAlign:'center', padding:'0 24px',
        opacity: visible ? 1 : 0,
        transform: visible ? 'translateY(0)' : 'translateY(28px)',
        transition:'opacity 0.75s ease, transform 0.75s ease',
      }}>
        <div style={{ fontSize:48, marginBottom:14, display:'inline-block', animation: success ? 'heartbeat 0.4s ease' : 'floatA 4s ease-in-out infinite' }}>
          {success ? '✅' : '🔐'}
        </div>
        <h2 style={{ fontSize:24, fontWeight:800, color:'#9D174D', marginBottom:6, letterSpacing:-0.5 }}>
          {success ? '欢迎！Melody ✦' : '输入密码'}
        </h2>
        <p style={{ color:'#F9A8D4', fontSize:13, marginBottom:28 }}>
          {success ? '正在进入…' : 'Enter your PIN to continue'}
        </p>

        {/* Dots */}
        <div style={{
          display:'flex', gap:18, justifyContent:'center', marginBottom:36,
          animation: shake ? 'shakePIN 0.6s ease' : 'none',
        }}>
          {[0,1,2,3].map(i => (
            <div key={i} style={{
              width:14, height:14, borderRadius:'50%',
              background: success ? '#22c55e' : i < pin.length ? '#DB2777' : 'transparent',
              border:'2px solid',
              borderColor: success ? '#22c55e' : i < pin.length ? '#DB2777' : shake ? '#F87171' : '#F9A8D4',
              transition:'all 0.2s',
              transform: i < pin.length ? 'scale(1.18)' : 'scale(1)',
            }} />
          ))}
        </div>

        {/* Keypad */}
        <div style={{ display:'grid', gridTemplateColumns:'repeat(3, 64px)', gap:12, margin:'0 auto', width:'fit-content' }}>
          {keys.map((k, i) => (
            <button key={i} className={k ? 'pin-key' : ''}
              onClick={() => k === '⌫' ? handleDel() : k ? handleKey(k) : null}
              disabled={!k}
              style={{
                width:64, height:64, borderRadius:'50%',
                border: k ? '1.5px solid #FBCFE8' : 'none',
                background: k === '⌫' ? '#FFF0F7' : k ? '#fff' : 'transparent',
                color: k === '⌫' ? '#DB2777' : '#9D174D',
                fontSize: k === '⌫' ? 20 : 22,
                fontWeight:600, cursor: k ? 'pointer' : 'default',
                boxShadow: k && k !== '⌫' ? '0 2px 8px rgba(244,114,182,0.12)' : 'none',
                transition:'all 0.15s',
              }}
            >{k}</button>
          ))}
        </div>
      </div>
    </div>
  )
}

/* ── Main App ── */
export default function App() {
  const [screen, setScreen] = useState('welcome')
  const [input, setInput] = useState('')
  const [parts, setParts] = useState([])
  const [animating, setAnimating] = useState(false)
  const [decoded, setDecoded] = useState(false)
  const [search, setSearch] = useState('')
  const [activeTab, setActiveTab] = useState('全部')
  const [copied, setCopied] = useState(false)
  const textareaRef = useRef(null)

  const visibleKeys = (() => {
    let keys = Object.keys(ABBREVIATIONS)
    if (activeTab !== '全部' && CATEGORIES[activeTab]) keys = keys.filter(k => CATEGORIES[activeTab].includes(k))
    if (search) {
      const s = search.toLowerCase()
      keys = keys.filter(k => k.toLowerCase().includes(s) || ABBREVIATIONS[k].toLowerCase().includes(s))
    }
    return keys
  })()

  const handleDecode = useCallback(() => {
    if (!input.trim()) return
    const newParts = buildDecodedParts(input)
    setParts(newParts)
    setAnimating(true)
    setDecoded(true)
    setTimeout(() => setAnimating(false), newParts.length * 30 + 200)
  }, [input])

  const handleCardClick = (abbr) => {
    setInput(abbr)
    const newParts = buildDecodedParts(abbr)
    setParts(newParts)
    setAnimating(true)
    setDecoded(true)
    setTimeout(() => setAnimating(false), newParts.length * 30 + 200)
    window.scrollTo({ top: 0, behavior: 'smooth' })
  }

  const handleCopy = () => {
    const plain = parts.map(p => p.type === 'text' ? p.text : `${p.text} (${p.meaning})`).join('')
    navigator.clipboard.writeText(plain)
    setCopied(true)
    setTimeout(() => setCopied(false), 1800)
  }

  const handleClear = () => {
    setInput('')
    setParts([])
    setDecoded(false)
    setAnimating(false)
    textareaRef.current?.focus()
  }

  const abbrCount = parts.filter(p => p.type === 'abbr').length

  return (
    <>
      <style>{GLOBAL_STYLES}</style>

      {screen === 'welcome' && <WelcomeScreen onContinue={() => setScreen('password')} />}
      {screen === 'password' && <PasswordScreen onUnlock={() => setScreen('app')} />}

      <div style={{
        minHeight:'100vh',
        backgroundColor:'#FFF0F7',
        backgroundImage:`linear-gradient(rgba(255,240,247,0.82), rgba(253,244,255,0.86)), url(${MY_MELODY_BG})`,
        backgroundSize:'cover',
        backgroundPosition:'center top',
        backgroundRepeat:'no-repeat',
        backgroundAttachment:'fixed',
        paddingBottom:80,
        visibility: screen === 'app' ? 'visible' : 'hidden',
        opacity: screen === 'app' ? 1 : 0,
        transition:'opacity 0.5s ease',
      }}>

        {/* ── Header ── */}
        <div style={{
          background:'linear-gradient(160deg, #FFF0F7 0%, #FDF4FF 50%, #FFF0F7 100%)',
          borderBottom:'1px solid #FBCFE8',
          padding:'44px 20px 56px',
          textAlign:'center',
          position:'relative',
          overflow:'hidden',
        }}>
          {/* animated blobs */}
          <div style={{ position:'absolute', top:-40, left:-40, width:180, height:180, borderRadius:'50%', background:'rgba(244,114,182,0.09)', pointerEvents:'none', animation:'driftBlob 8s ease-in-out infinite' }} />
          <div style={{ position:'absolute', top:-20, right:-30, width:140, height:140, borderRadius:'50%', background:'rgba(217,70,239,0.07)', pointerEvents:'none', animation:'driftBlob 10s ease-in-out 2s infinite' }} />
          <div style={{ position:'absolute', bottom:-20, left:'35%', width:90, height:90, borderRadius:'50%', background:'rgba(244,114,182,0.06)', pointerEvents:'none', animation:'driftBlob 7s ease-in-out 1s infinite' }} />
          {/* floating emoji */}
          <div style={{ position:'absolute', top:22, left:'9%', fontSize:22, animation:'floatA 5s ease-in-out infinite', pointerEvents:'none', opacity:0.45 }}>🌸</div>
          <div style={{ position:'absolute', top:28, right:'11%', fontSize:18, animation:'floatB 4.5s ease-in-out 1s infinite', pointerEvents:'none', opacity:0.45 }}>🌟</div>
          <div style={{ position:'absolute', bottom:22, left:'20%', fontSize:16, animation:'floatA 6s ease-in-out 2s infinite', pointerEvents:'none', opacity:0.38 }}>✨</div>
          <div style={{ position:'absolute', bottom:18, right:'17%', fontSize:20, animation:'floatB 5.5s ease-in-out 0.5s infinite', pointerEvents:'none', opacity:0.42 }}>🐚</div>

          <div style={{
            display:'inline-flex', alignItems:'center', gap:6,
            background:'#fff', border:'1px solid #FBCFE8', borderRadius:99,
            padding:'5px 16px', fontSize:12, color:'#DB2777', fontWeight:600,
            marginBottom:20, letterSpacing:0.4,
            boxShadow:'0 2px 8px rgba(244,114,182,0.12)',
            position:'relative', zIndex:2,
            animation:'fadeUp 0.6s ease',
          }}>
            ✦ 网络用语解码工具
          </div>

          <h1 style={{ fontSize:38, fontWeight:800, letterSpacing:-1.5, lineHeight:1.1, marginBottom:14, position:'relative', zIndex:2, animation:'fadeUp 0.7s ease' }}>
            <span style={{ color:'#DB2777' }}>短信</span>
            <span style={{ color:'#0EA5E9' }}>解码器</span>
          </h1>
          <p style={{ color:'#BE185D', opacity:0.7, fontSize:15, maxWidth:360, margin:'0 auto', lineHeight:1.6, position:'relative', zIndex:2, animation:'fadeUp 0.8s ease' }}>
            看不懂英文缩写？粘贴消息，一键解码所有网络用语
          </p>
        </div>

        <div style={{ maxWidth:700, margin:'0 auto', padding:'0 16px', position:'relative', zIndex:1 }}>

          {/* ── Decoder card ── */}
          <div style={{
            background:'#fff', borderRadius:28,
            border:'1.5px solid #FBCFE8', padding:24,
            marginTop:-28,
            boxShadow:'0 8px 40px rgba(219,39,119,0.1)',
            animation:'fadeUp 0.5s ease',
          }}>
            <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:14 }}>

              {/* Input */}
              <div style={{ minWidth:0 }}>
                <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:8 }}>
                  <span style={{ fontSize:11, fontWeight:700, color:'#F9A8D4', letterSpacing:'0.1em' }}>输入消息</span>
                  {input && (
                    <button onClick={handleClear} style={{ background:'none', border:'none', color:'#F9A8D4', fontSize:12, padding:'2px 6px', borderRadius:6, cursor:'pointer' }}>清除 ×</button>
                  )}
                </div>
                <textarea
                  ref={textareaRef}
                  value={input}
                  onChange={e => setInput(e.target.value)}
                  onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleDecode() } }}
                  placeholder="例如：omg lol btw wyd rn?"
                  style={{
                    width:'100%', height:110, display:'block',
                    border:'1.5px solid #FBCFE8', borderRadius:14, padding:'12px 14px',
                    fontSize:14, color:'#6B21A8', background:'#FFF9FC',
                    outline:'none', lineHeight:1.6,
                    transition:'border-color 0.15s, box-shadow 0.15s',
                    resize:'none',
                  }}
                />
                <p style={{ fontSize:11, color:'#F9A8D4', marginTop:6 }}>按 Enter 解码 · Shift+Enter 换行</p>
              </div>

              {/* Output */}
              <div style={{ minWidth:0 }}>
                <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:8 }}>
                  <span style={{ fontSize:11, fontWeight:700, color:'#F9A8D4', letterSpacing:'0.1em' }}>解码结果</span>
                  {decoded && parts.length > 0 && (
                    <button onClick={handleCopy} style={{
                      background: copied ? '#FFF0F7' : 'none',
                      border:'none', color: copied ? '#DB2777' : '#F9A8D4',
                      fontSize:12, padding:'2px 8px', borderRadius:6, transition:'all 0.2s', cursor:'pointer',
                    }}>{copied ? '已复制 ✓' : '复制'}</button>
                  )}
                </div>
                <div style={{
                  width:'100%', minHeight:110,
                  border:'1.5px solid #FBCFE8', borderRadius:14, padding:'12px 14px',
                  background:'#FFF9FC', overflowWrap:'break-word', wordBreak:'break-word', overflow:'hidden',
                }}>
                  {decoded && parts.length > 0
                    ? <DecodedOutput parts={parts} animating={animating} />
                    : <span style={{ color:'#F9A8D4', fontSize:14 }}>翻译结果显示在这里…</span>
                  }
                </div>
                {decoded && abbrCount > 0 && (
                  <p style={{ fontSize:11, color:'#EC4899', marginTop:6 }}>✦ 找到 {abbrCount} 个缩写</p>
                )}
              </div>
            </div>

            {/* Decode button */}
            <button className="decode-btn" onClick={handleDecode} disabled={!input.trim()} style={{
              width:'100%', marginTop:18, padding:'14px 0',
              background: input.trim() ? 'linear-gradient(135deg, #EC4899 0%, #A21CAF 100%)' : '#FBCFE8',
              border:'none', borderRadius:16,
              color: input.trim() ? '#fff' : '#F9A8D4',
              fontSize:15, fontWeight:700, letterSpacing:0.5,
              transition:'all 0.2s', cursor: input.trim() ? 'pointer' : 'default',
              boxShadow: input.trim() ? '0 4px 18px rgba(219,39,119,0.28)' : 'none',
            }}>
              {animating ? '解码中 ✦' : '一键解码'}
            </button>
          </div>

          {/* ── Browse section ── */}
          <div style={{ marginTop:44 }}>
            <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:16 }}>
              <h2 style={{ fontSize:18, fontWeight:700, color:'#9D174D' }}>浏览所有缩写</h2>
              <span style={{ fontSize:13, color:'#F9A8D4' }}>共 {visibleKeys.length} 个</span>
            </div>

            {/* Search */}
            <div style={{ position:'relative', marginBottom:16 }}>
              <span style={{ position:'absolute', left:14, top:'50%', transform:'translateY(-50%)', color:'#F9A8D4', fontSize:16, pointerEvents:'none' }}>✦</span>
              <input className="search-input" type="text" value={search}
                onChange={e => setSearch(e.target.value)}
                placeholder="搜索缩写或含义…"
                style={{
                  width:'100%', padding:'11px 40px 11px 40px',
                  border:'1.5px solid #FBCFE8', borderRadius:14,
                  fontSize:14, color:'#6B21A8', background:'#fff',
                  outline:'none', transition:'border-color 0.15s, box-shadow 0.15s', display:'block',
                }}
              />
              {search && (
                <button onClick={() => setSearch('')} style={{
                  position:'absolute', right:12, top:'50%', transform:'translateY(-50%)',
                  background:'none', border:'none', color:'#F9A8D4', fontSize:18, cursor:'pointer',
                }}>×</button>
              )}
            </div>

            {/* Tabs */}
            <div style={{ display:'flex', gap:6, flexWrap:'wrap', marginBottom:20 }}>
              {Object.keys(CATEGORIES).map(tab => (
                <button key={tab} className="tab-btn" onClick={() => setActiveTab(tab)} style={{
                  fontSize:12, padding:'5px 13px', borderRadius:99,
                  border: activeTab === tab ? '1.5px solid #F472B6' : '1.5px solid #FBCFE8',
                  background: activeTab === tab ? '#FFF0F7' : '#fff',
                  color: activeTab === tab ? '#BE185D' : '#F9A8D4',
                  fontWeight: activeTab === tab ? 700 : 400,
                  transition:'all 0.15s', cursor:'pointer',
                }}>{tab}</button>
              ))}
            </div>

            {/* Cards */}
            {visibleKeys.length === 0 ? (
              <div style={{ textAlign:'center', padding:'3rem', color:'#F9A8D4', fontSize:14 }}>
                没有找到相关缩写，换个关键词试试 ✦
              </div>
            ) : (
              <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fill, minmax(130px, 1fr))', gap:10 }}>
                {visibleKeys.map(k => (
                  <div key={k} className="card-wrap">
                    <CardFlip abbr={k} meaning={ABBREVIATIONS[k]} onClick={handleCardClick} />
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
      <Analytics />
    </>
  )
}
